const e = $('Entree H').first().json;
const rows = $input.all().map(x => x.json).filter(r => r && r.modele);
const C = e.code;
const parse = r => { try { return JSON.parse(r.codes); } catch (_) { return []; } };
const isList = c => /[a-z]{3,}/i.test(c) && c.length > 5;
const nc = c => String(c).toUpperCase().replace(/\.$/, '');
const findCode = list => { const ex = list.filter(([c]) => nc(c) === C); return ex.length ? ex : list.filter(([c]) => nc(c).startsWith(C + '-')); };
const url = (p, a) => 'https://hitachi-mp.spelog.com/getalarmcode.aspx?P=' + encodeURIComponent(p) + '&L=FR&A=' + encodeURIComponent(a);
const out = o => [{ json: Object.assign({ action: 'texte', absent: false, resultat: '', url: '', cle: '', modele: '', libelle: '', code_fiche: '', liste: false }, o) }];
const SRC = 'Source : application officielle Hitachi airCloud Alarm Code (fiches du manuel de service Hitachi).';
if (!C) return out({ resultat: 'Aucun code fourni : demander le code exact affiche (telecommande, afficheur du groupe exterieur ou clignotements du voyant).' });
if (!e.pref) {
  const by = {};
  rows.forEach(r => findCode(parse(r)).forEach(([c, d]) => { const k = String(d || '').trim(); if (k) (by[k] = by[k] || new Set()).add(r.famille); }));
  const ent = Object.entries(by).sort((a, b) => b[1].size - a[1].size).slice(0, 8);
  if (!ent.length) return out({ absent: true, resultat: 'Code ' + C + ' introuvable dans la base Hitachi. Ne devine pas sa signification. Demande le modele exact (plaque) et la lecture exacte du code. Laurent a ete prevenu.' });
  return out({ resultat: SRC + '\nModele non fourni : chez Hitachi le libelle et la fiche de depannage dependent du modele. Libelles connus pour le code ' + C + ' (familles de modeles entre crochets) :\n' + ent.map(([d, s]) => '- ' + d + ' [' + [...s].slice(0, 8).join(', ') + ']').join('\n') + '\nDemande le modele exact (plaque signaletique de l unite interieure ou du groupe exterieur) pour obtenir la fiche de depannage officielle avec les verifications.' });
}
let cands = rows.filter(r => r.modele_norm === e.norm);
if (!cands.length) cands = rows.filter(r => r.modele_norm.startsWith(e.norm) || e.norm.startsWith(r.modele_norm));
if (!cands.length && rows.length) {
  const lcp = (a, b) => { let i = 0; while (i < a.length && a[i] === b[i]) i++; return i; };
  const best = Math.max(...rows.map(r => lcp(r.modele_norm, e.norm)));
  if (best >= e.pref.length + 2) cands = rows.filter(r => lcp(r.modele_norm, e.norm) === best);
}
if (!cands.length) return out({ resultat: 'Modele ' + e.modele + ' non trouve dans la base Hitachi.' + (rows.length ? ' Modeles proches : ' + rows.slice(0, 8).map(r => r.modele).join(', ') + '.' : '') + ' Verifie la plaque : si ce n est pas un Hitachi (ex : un RAS Toshiba), relance avec la bonne marque. Sinon redemande le modele exact.' });
const x = cands.map(r => ({ r, hits: findCode(parse(r)), list: parse(r).filter(([c]) => isList(c)) }));
const ok = x.filter(y => y.hits.length);
const sig = y => y.hits.map(h => h[1]).join(' / ');
let pick = null;
if (ok.length === 1 || (ok.length > 1 && new Set(ok.map(sig)).size === 1)) pick = ok[0];
if (!pick && ok.length > 1) return out({ resultat: SRC + '\nPlusieurs modeles Hitachi correspondent a ' + e.modele + ' : ' + ok.slice(0, 8).map(y => y.r.modele).join(', ') + '.\nLibelles du code ' + C + ' selon le modele :\n' + [...new Set(ok.map(sig))].slice(0, 5).map(d => '- ' + d).join('\n') + '\nDemande le modele exact sur la plaque pour avoir la fiche de depannage complete.' });
if (pick) {
  const [c, d] = pick.hits[0];
  const autres = pick.hits.slice(1).map(h => h[0] + ' : ' + h[1]);
  return out({ action: 'fiche', modele: pick.r.modele, libelle: 'Code ' + c + ' : ' + d + (autres.length ? '\nSous-codes : ' + autres.join(' ; ') : ''), url: url(pick.r.p, c), cle: pick.r.p + '|' + c, code_fiche: c, resultat: SRC });
}
const lo = x.find(y => y.list.length);
if (lo) return out({ action: 'fiche', liste: true, modele: lo.r.modele, libelle: 'Pour ce modele, Hitachi fournit une liste globale des codes (clignotements du voyant ou affichage), pas une fiche par code. Code demande : ' + C + '.', url: url(lo.r.p, lo.list[0][0]), cle: lo.r.p + '|' + C, code_fiche: C, resultat: SRC });
return out({ absent: true, resultat: 'Le code ' + C + ' n existe pas pour le modele ' + cands[0].modele + ' dans la base Hitachi. Codes connus pour ce modele : ' + parse(cands[0]).map(([c]) => c).slice(0, 60).join(', ') + '. Fais verifier la lecture (code complet avec sous-code, afficheur du groupe exterieur ou telecommande). Ne devine pas. Laurent a ete prevenu.' });

const i = $input.first().json || {};
const raw = String(i.modele || '').toUpperCase().replace(/\s+/g, '');
const norm = raw.replace(/\.0(?=[A-Z])/g, '').replace(/[^A-Z0-9.]/g, '');
const m = /^([A-Z]+\d+(?:\.\d+)?)/.exec(norm);
const pref = m ? m[1] : '';
let code = String(i.code || '').trim().replace(/^(code|erreur|error|alarme|alarm|defaut|défaut)\s*/i, '').replace(/\.$/, '').trim();
if (/^\d$/.test(code)) code = '0' + code;
code = code.toUpperCase();
const sansModele = !pref;
return [{ json: { modele: raw, norm, pref, code, demandeur: String(i.demandeur || ''), col: sansModele ? 'codes' : 'modele_norm', cond: sansModele ? 'ilike' : 'like', val: sansModele ? '%["' + (code || 'AUCUN') + '%' : pref + '%' } }];

